<?php $pageTitle='Dashboard'; require_once __DIR__.'/includes/header.php'; require_once __DIR__.'/includes/sidebar.php'; $db=getDB();$club=$_SESSION['club_id'];$today=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sessions WHERE club_id=? AND status='completed' AND DATE(end_time)=CURDATE()");$today->execute([$club]);$revenue=(float)$today->fetchColumn();$active=$db->prepare("SELECT COUNT(*) FROM sessions WHERE club_id=? AND status IN ('running','paused')");$active->execute([$club]);$expenses=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE club_id=? AND expense_date=CURDATE()');$expenses->execute([$club]);$expenses=(float)$expenses->fetchColumn();$players=$db->prepare('SELECT COUNT(*) FROM players WHERE club_id=? AND is_active=1');$players->execute([$club]);$players=(int)$players->fetchColumn();$month=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sessions WHERE club_id=? AND status='completed' AND DATE_FORMAT(end_time,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')");$month->execute([$club]);$monthly=(float)$month->fetchColumn();$cafe=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM cafe_orders WHERE club_id=? AND status='completed' AND DATE(created_at)=CURDATE()");$cafe->execute([$club]);$cafe=(float)$cafe->fetchColumn();$daily=$db->prepare("SELECT DATE(end_time) d,SUM(total_amount) total FROM sessions WHERE club_id=? AND status='completed' AND end_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) GROUP BY DATE(end_time) ORDER BY d");$daily->execute([$club]);$chart=$daily->fetchAll(); ?>
<div class="flex justify-between items-center mb-6"><div><h1 class="text-2xl font-bold">Good day, <?=sanitize(explode(' ',$_SESSION['user_name'])[0])?></h1><p class="text-slate-400 text-sm mt-1">Here is how your club is performing today.</p></div><a href="<?=url('operator.php')?>" class="btn-primary"><i class="fa-solid fa-table-cells-large mr-2"></i>Open Floor</a></div><div class="grid grid-cols-2 xl:grid-cols-4 gap-4"><div class="card"><p class="text-xs uppercase text-slate-400">Today's Revenue</p><p class="text-2xl font-extrabold mt-2 text-green-400"><?=money($revenue)?></p></div><div class="card"><p class="text-xs uppercase text-slate-400">Active Sessions</p><p class="text-2xl font-extrabold mt-2 text-red-400"><?=$active->fetchColumn()?> tables</p></div><div class="card"><p class="text-xs uppercase text-slate-400">Today's Expenses</p><p class="text-2xl font-extrabold mt-2 text-orange-400"><?=money($expenses)?></p></div><div class="card"><p class="text-xs uppercase text-slate-400">Net Profit Today</p><p class="text-2xl font-extrabold mt-2 text-emerald-400"><?=money($revenue-$expenses)?></p></div></div><div class="grid md:grid-cols-3 gap-4 mt-4"><div class="card"><p class="text-xs uppercase text-slate-400">This Month Revenue</p><p class="text-xl font-bold mt-2"><?=money($monthly)?></p></div><div class="card"><p class="text-xs uppercase text-slate-400">Total Players</p><p class="text-xl font-bold mt-2"><?=$players?></p></div><div class="card"><p class="text-xs uppercase text-slate-400">Café Sales Today</p><p class="text-xl font-bold mt-2"><?=money($cafe)?></p></div></div><div class="grid xl:grid-cols-5 gap-4 mt-5"><section class="card xl:col-span-3"><h2 class="font-bold mb-4">Daily Revenue</h2><canvas id="revenueChart" height="100"></canvas></section><section class="card xl:col-span-2"><h2 class="font-bold mb-4">Revenue Sources Today</h2><canvas id="sourceChart"></canvas></section></div><section class="card mt-5"><div class="flex justify-between"><h2 class="font-bold">Quick actions</h2><span class="text-xs text-slate-500">Live data updates with each operation</span></div><div class="flex flex-wrap gap-3 mt-4"><a class="btn-secondary" href="<?=url('modules/expenses.php')?>"><i class="fa-solid fa-plus mr-1"></i>Add Expense</a><a class="btn-secondary" href="<?=url('modules/players.php')?>"><i class="fa-solid fa-user-plus mr-1"></i>Add Player</a><a class="btn-secondary" href="<?=url('modules/reports.php')?>"><i class="fa-solid fa-chart-line mr-1"></i>View Reports</a><a class="btn-secondary" href="<?=url('modules/shifts.php')?>"><i class="fa-solid fa-cash-register mr-1"></i>Open Shift</a></div></section><script>new Chart(document.getElementById('revenueChart'),{type:'line',data:{labels:<?=json_encode(array_column($chart,'d'))?>,datasets:[{label:'Revenue',data:<?=json_encode(array_map('floatval',array_column($chart,'total')))?>,borderColor:'#22c55e',backgroundColor:'#22c55e22',fill:true,tension:.35}]},options:{plugins:{legend:{labels:{color:'#cbd5e1'}},},scales:{x:{ticks:{color:'#94a3b8'},grid:{color:'#334155'}},y:{ticks:{color:'#94a3b8'},grid:{color:'#334155'}}}}});new Chart(document.getElementById('sourceChart'),{type:'doughnut',data:{labels:['Tables','Café'],datasets:[{data:[<?=$revenue?>,<?=$cafe?>],backgroundColor:['#22c55e','#3b82f6']}]},options:{plugins:{legend:{labels:{color:'#cbd5e1'}}}}});</script><?php require __DIR__.'/includes/footer.php'; ?>
